// Validate the Worker's payload and output one item per demo.
const body = $json.body ?? {};
const errors = [];

const ranAt = new Date(body.ran_at);
if (!body.ran_at || isNaN(ranAt)) errors.push('ran_at missing or not a valid ISO date');
if (!Array.isArray(body.demos) || body.demos.length === 0) errors.push('demos must be a non-empty array');
if (Array.isArray(body.demos) && body.demos.length > 50) errors.push('too many demos (max 50)');
if (errors.length) throw new Error('Invalid payload: ' + errors.join('; '));

const int = (v) => (Number.isFinite(Number(v)) && v !== null && v !== '' ? Math.round(Number(v)) : null);
const text = (v, max) => (v === null || v === undefined || v === '' ? null : String(v).slice(0, max));

return body.demos.map((d, i) => {
  const name = String(d?.name ?? '').trim();
  if (!/^[\w .-]{1,60}$/.test(name)) throw new Error(`Invalid demo name at index ${i}`);
  if (typeof d.ok !== 'boolean') throw new Error(`"ok" must be true or false for ${name}`);
  return {
    json: {
      run_at: ranAt.toISOString(),
      demo: name,
      ok: d.ok,
      wake_ms: int(d.wake_ms),
      page_ms: int(d.page_ms),
      status_code: int(d.status_code),
      problem: text(d.problem, 500),
      details: d.details && typeof d.details === 'object' ? JSON.stringify(d.details).slice(0, 4000) : null,
      source: text(body.source, 60) ?? 'cloudflare-worker',
    },
  };
});

