// Build the Telegram report: this run, 7-day uptime, slow wake-ups and failure streaks.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const secs = (ms) => (ms / 1000).toFixed(1) + 's';

// Slow-wake rule: needs at least 3 earlier successful runs as a baseline.
const MIN_BASELINE_RUNS = 3;
const SLOW_FACTOR = 1.5;        // 50% slower than usual...
const SLOW_MIN_EXTRA_MS = 20000; // ...and at least 20s slower (polls are 20s apart)
const SLOW_ABSOLUTE_MS = 120000; // anything over 2 minutes is always slow

const run = $('Validate & flatten').all().map((i) => i.json);
const stats = Object.fromEntries(
  $input.all().filter((i) => i.json.demo).map((i) => [i.json.demo, i.json])
);

let down = 0, slow = 0;
const lines = run
  .sort((a, b) => a.demo.localeCompare(b.demo))
  .map((d) => {
    const s = stats[d.demo] ?? {};
    const week = s.uptime_pct != null ? ` · 7d ${s.uptime_pct}%` : '';

    if (!d.ok) {
      down++;
      const streak = Number(s.fail_streak) >= 2 ? ` (${s.fail_streak} runs in a row)` : '';
      const why = d.problem ? `\n     ${esc(d.problem)}` : '';
      return `❌ <b>${esc(d.demo)}</b>: DOWN${streak}${week}${why}`;
    }

    if (d.wake_ms == null) return `✅ <b>${esc(d.demo)}</b>: up${week}`;

    const usual = Number(s.usual_wake_ms);
    const hasBaseline = Number(s.baseline_runs) >= MIN_BASELINE_RUNS && usual > 0;
    const isSlow =
      d.wake_ms > SLOW_ABSOLUTE_MS ||
      (hasBaseline && d.wake_ms > usual * SLOW_FACTOR && d.wake_ms - usual >= SLOW_MIN_EXTRA_MS);

    if (isSlow) {
      slow++;
      const vs = hasBaseline ? ` (usually ${secs(usual)})` : '';
      return `🐢 <b>${esc(d.demo)}</b>: slow, woke in ${secs(d.wake_ms)}${vs}${week}`;
    }
    return `✅ <b>${esc(d.demo)}</b>: woke in ${secs(d.wake_ms)}${week}`;
  });

const when = DateTime.fromISO(run[0].run_at).setZone('Asia/Dubai').toFormat('dd LLL, HH:mm');
let header;
if (down) header = `🚨 <b>Demo check: ${down} of ${run.length} down</b>`;
else if (slow) header = `🟡 <b>Demo check: all ${run.length} up, ${slow} slow</b>`;
else header = `🟢 <b>Demo check: all ${run.length} up</b>`;

return [{
  json: {
    text: `${header}\n<i>${when} (Dubai)</i>\n\n${lines.join('\n')}`,
    silent: down === 0, // only failures ring; slow wake-ups arrive silently
    down, slow,
  },
}];

