// Weekly summary: last 7 days per demo, compared with the 7 days before.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = $input.all().map((i) => i.json).filter((r) => r.demo);

const end = $now.setZone('Asia/Dubai');
const range = `${end.minus({ days: 6 }).toFormat('dd LLL')} to ${end.toFormat('dd LLL')}`;

if (rows.length === 0) {
  return [{ json: { text: `📅 <b>Weekly demo summary</b>\n<i>${range}</i>\n\nNo demo checks were recorded in the last 7 days.` } }];
}

const pct = (ok, n) => (n > 0 ? Math.round((100 * ok) / n) : null);
let totalChecks = 0, totalPassed = 0;

const lines = rows.map((r) => {
  const checks = Number(r.checks), passed = Number(r.passed);
  totalChecks += checks; totalPassed += passed;
  const up = pct(passed, checks);
  const prevUp = pct(Number(r.prev_passed), Number(r.prev_checks));

  const icon = checks === 0 ? '⚪' : up === 100 ? '✅' : up >= 80 ? '🟡' : '❌';
  let line = `${icon} <b>${esc(r.demo)}</b>: ${up ?? '-'}% up (${passed}/${checks})`;
  if (prevUp != null && up != null && prevUp !== up) line += `, was ${prevUp}%`;

  if (r.avg_wake_s != null) {
    line += `\n     wake avg ${r.avg_wake_s}s, slowest ${r.max_wake_s}s`;
    if (r.prev_avg_wake_s != null) {
      const diff = Number(r.avg_wake_s) - Number(r.prev_avg_wake_s);
      if (Math.abs(diff) >= 5) line += ` (${diff > 0 ? '+' : ''}${diff.toFixed(1)}s vs last week)`;
    }
  }
  return line;
});

const overall = pct(totalPassed, totalChecks);
const header = `📅 <b>Weekly demo summary</b>\n<i>${range}</i>\n\nOverall: <b>${overall ?? '-'}%</b> (${totalPassed}/${totalChecks} checks passed)`;

return [{ json: { text: `${header}\n\n${lines.join('\n')}` } }];
